using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;
public static class PortalTileCapture{
 static string O=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/검수/2026-11-07_C01_PortalTiles/"));
 static void Shot(string n,Vector3 target,Vector3 pos,float fov){var go=new GameObject("Door_Review_Temporary");var c=go.AddComponent<Camera>();c.transform.position=pos;c.transform.LookAt(target);c.nearClipPlane=.02f;c.farClipPlane=180;c.fieldOfView=fov;c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.027f,.037f,.05f);c.GetUniversalAdditionalCameraData().renderPostProcessing=false;c.allowMSAA=true;var rt=new RenderTexture(1600,1000,24){antiAliasing=4};var prev=RenderTexture.active;Texture2D tex=null;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;tex=new Texture2D(1600,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,1000),0,0);tex.Apply();File.WriteAllBytes(O+n+".png",tex.EncodeToPNG());}finally{RenderTexture.active=prev;c.targetTexture=null;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
 public static object Before()=>Run("Before");public static object After()=>Run("After");
 static object Run(string prefix){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_B5_Circular.unity"))throw new Exception("Saved B5 edit scene required");Directory.CreateDirectory(O);var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var room=root.Find("C01_Experiment_Art");var doors=root.Find("Pocket_Doors_Open").Cast<Transform>().Where(d=>Vector3.Distance(d.position,room.position)<12).ToArray();var hidden=s.GetRootGameObjects().Where(g=>g.name.StartsWith("Player")).SelectMany(g=>g.GetComponentsInChildren<Renderer>()).ToDictionary(r=>r,r=>r.enabled);
 try{foreach(var r in hidden.Keys)r.enabled=false;foreach(var d in doors){var fw=(d.position-room.position).normalized;var right=Vector3.Cross(Vector3.up,fw);var at=d.position+Vector3.up*1.8f;Shot(prefix+"_"+d.name+"_Room",at,d.position-fw*5.3f+Vector3.up*1.75f,53);Shot(prefix+"_"+d.name+"_Tunnel",at,d.position+fw*4.6f+Vector3.up*1.8f,58);Shot(prefix+"_"+d.name+"_Joint",d.position+Vector3.up*2.95f,d.position-fw*2.3f+right*.9f+Vector3.up*2.35f,58);if(prefix=="ClosedReview"){foreach(string side in new[]{"Left","Right"})d.Find("Clinical_Portal/Leaf_"+side).localPosition=d.Find("Clinical_Portal/"+side+"_Closed").localPosition;Shot(prefix+"_"+d.name+"_Closed",at,d.position-fw*5.3f+Vector3.up*1.75f,53);foreach(string side in new[]{"Left","Right"})d.Find("Clinical_Portal/Leaf_"+side).localPosition=d.Find("Clinical_Portal/"+side+"_Open").localPosition;}}}finally{foreach(var kv in hidden)kv.Key.enabled=kv.Value;EditorSceneManager.OpenScene(s.path);}return new{prefix,doors=doors.Length,output=O};}
}
